import sys, random, json
from math import gcd
sys.path.insert(0, '/workspace/submission')
sys.path.insert(0, '/tmp/t')
import exact, gen, ref


def time_expanded(fab, g, hopfn, L):
    """dist[(t,i)] = min cost of a lineage ending at boundary t (events >= 0)."""
    N = fab['n']; T = fab['interval_ns']; S = fab['slice_ns']; O = fab['offset_ns']
    Q = len(fab['slices']); links = fab['links']
    P = (Q * S) // gcd(T, Q * S)
    v = [[fab['drift_ppb'][i]] * P for i in range(N)]
    for (node, s, e, ex) in fab['heat']:
        for p in range(s, e):
            v[node][p] += ex
    anch = [[False] * P for _ in range(N)]
    for (node, s, e) in fab['anchors']:
        for p in range(s, e):
            anch[node][p] = True
    blk = [[False] * P for _ in range(len(links))]
    for (l, s, e) in fab['blackouts']:
        for p in range(s, e):
            blk[l][p] = True
    INF = None
    dist = [[INF] * N for _ in range(L + 1)]
    # edges as (t, u, t2, w)
    edges = []
    for t in range(L + 1):
        for i in range(N):
            if t + 1 <= L:
                edges.append((t, i, t + 1, i, v[i][t % P] * T))
            if anch[i][t % P]:
                if dist[t][i] is None or dist[t][i] > 0:
                    dist[t][i] = 0
        q = ((O + t * T) // S) % Q
        rho = (O + t * T) % S
        for l in fab['slices'][q]:
            link = links[l]
            for dirc in (0, 1):
                if dirc == 0:
                    sn = link['ends'][0][0]; dn = link['ends'][1][0]
                    sc = link['ends'][0][2]; dc = link['ends'][1][2]
                    delay = link['delay_ns'][0]; defer = link['defer_rounds'][0]
                else:
                    sn = link['ends'][1][0]; dn = link['ends'][0][0]
                    sc = link['ends'][1][2]; dc = link['ends'][0][2]
                    delay = link['delay_ns'][1]; defer = link['defer_rounds'][1]
                if rho < g or rho + delay + g > S:
                    continue
                j = -((-delay) // T)
                bad = any(blk[l][(t + u) % P] for u in range(j))
                if bad:
                    continue
                m = j + defer
                if t + m > L:
                    continue
                partial = j * T - delay
                ageing = v[dn][(t + j - 1) % P] * partial
                for u in range(j, m):
                    ageing += v[dn][(t + u) % P] * T
                edges.append((t, sn, t + m, dn, hopfn(sc, dc) + ageing))
    # Bellman-Ford
    for _ in range((L + 1) * N + 2):
        ch = False
        for (t, u, t2, w2, c) in edges:
            if dist[t][u] is None:
                continue
            nd = dist[t][u] + c
            if dist[t2][w2] is None or nd < dist[t2][w2]:
                dist[t2][w2] = nd
                ch = True
        if not ch:
            break
    else:
        raise AssertionError('no convergence')
    return P, N, dist


rng = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 0)
bad = 0
n = 0
for it in range(40):
    prof = gen.gen_profile(rng)
    fab = gen.gen_fabric(rng, prof)
    feas, upper, _ = ref.ref_calib(prof)
    if not feas:
        continue
    calib = exact.Calibration(prof)
    F = exact.Fabric(fab, calib)
    plan = exact.compile_plan(prof, fab)
    if plan['guard_ns'] is None:
        continue
    g = plan['guard_ns']
    env = F.envelope(g)
    P, N = F.P, F.N
    L = 5 * P + 40
    P2, N2, dist = time_expanded(fab, g, calib.hop_as, L)
    assert (P, N) == (P2, N2)
    # periodic envelope must match the converged time-expanded distances
    for t in range(4 * P, 5 * P):
        for i in range(N):
            if dist[t][i] != env[0][(t % P) * N + i]:
                print('ENVELOPE MISMATCH', t, i, dist[t][i], env[0][(t % P) * N + i])
                bad += 1
    # warmup
    k = None
    for c in range(0, 5):
        ok = True
        for t in range(c * P, (c + 1) * P):
            for i in range(N):
                if dist[t][i] != env[0][(t % P) * N + i]:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            k = c
            break
    n += 1
    if k != plan['warmup_cycle']:
        print('WARMUP MISMATCH: brute', k, 'ours', plan['warmup_cycle'])
        print(json.dumps(prof)); print(json.dumps(fab))
        bad += 1
print('checked', n, 'bad =', bad)
