            if chosen is None and pk is not None and g * NS_AS >= pk + reconf:
                chosen = g
                chosen_env = env
                env = None
        peaks.append(pk)
        if chosen is None and pk is not None and g * NS_AS >= pk + reconf:
            chosen = g
    return peaks, chosen, chosen_env

